flat=[]
for w,groups15 in enumerate(weeks):
    assign=[None]*30
    for gi,tr in enumerate(groups15):
        for p in tr: assign[p]=gi
        for p in tr: assign[p+15]=gi+5
    assert all(x is not None for x in assign)
    flat += assign
print(len(flat))
