# verify group sizes and pair repeats
seen={}
for w in range(7):
    groups={g:[] for g in range(10)}
    for p,g in enumerate(flat[w*30:(w+1)*30]):
        groups[g].append(p)
    print('week',w, groups)
    assert all(len(v)==3 for v in groups.values())
    for tr in groups.values():
        for i in range(3):
            for j in range(i+1,3):
                pair=tuple(sorted((tr[i],tr[j])))
                if pair in seen:
                    print('repeat',pair,seen[pair],w)
                    raise SystemExit
                seen[pair]=w
print('pairs',len(seen))
